const fs = await import("node:fs");
const p = "C:/Users/jjq21/AppData/Local/Temp/ofm-subs-out.txt";
const t = fs.readFileSync(p, "utf8");
console.log("LEN:", t.length);
// 只打印每个 sub 的标题行和 section 头
const lines = t.split("\n");
let cur = "";
for (const l of lines) {
  if (l.startsWith("##########")) { console.log("\n" + l); continue; }
  if (l.startsWith("ENTRIES")) { console.log(l); continue; }
  if (l.startsWith("--- ")) { console.log("  " + l.slice(4, 130)); }
}
